"""Render only audited completed evidence; no planned rows as results."""
import json,csv,statistics,collections
from v3_common import *
from continuation_statistics import fixed_program_bootstrap
audit=json.loads((OUT/'reports/G7_AUDIT.json').read_text());assert audit['status']=='PASS'
main=json.loads((OUT/'reports/CPU_EVALUATION_SUMMARY.json').read_text())
pairs=json.loads((OUT/'reports/CPU_EVALUATION_PAIRS.json').read_text())['pairs']
whole=json.loads((OUT/'reports/B_WHOLE_EVALUATION_SUMMARY.json').read_text());sparse=json.loads((OUT/'reports/B_SPARSE_SUMMARY.json').read_text())
freeze=json.loads((OUT/'configs/CANDIDATE_SPEC.lock.json').read_text());variants=[v['id'] for v in freeze['variants']]
def fmt(x):
 if x['mean'] is None:return 'insufficient owners'
 return f"{x['mean']:+.4f} [{x['CI95'][0]:+.4f}, {x['CI95'][1]:+.4f}]"
def comparison(rows,scenario=None):
 by={(r['program'],r['owner'],r.get('scenario',scenario),r['variant']):r for r in rows};group=collections.defaultdict(list)
 for r in rows:
  if r['variant']!='V3_P' or scenario and r.get('scenario',scenario)!=scenario:continue
  n=by.get((r['program'],r['owner'],r.get('scenario',scenario),'N1'))
  if n:group[r['program']].append(100*(n['D']-r['D'])/r['A'])
 return fixed_program_bootstrap(group,iterations=10000,seed=8171026) if group else dict(mean=None,CI95=None)
comparisons={s:comparison(pairs,s) for s in ['SBU_SINGLE','CHARM_6T','CERN_P29_INTERLEAVED']}
comparisons['WHOLE_EQUAL_PER_BIT_SBU']=comparison(whole['pairs']);comparisons['SPARSE_CHARM']=comparison(sparse['pairs'])
clean=main['clean_rows'];base={r['program']:r['cycles'] for r in clean if r['variant']=='P0'}
write(OUT/'reports/NEW_VS_N1.json',dict(status='MATCHED_OWNER_ANALYSIS',P_minus_N1_net_pp=comparisons,positive='N1 fault cycles minus P fault cycles, divided by same clean P0 A; P clean costs equal N1 only when observed',fixed_programs=True))
text=['# v3 software 결과','',f"이전 연구 파일 {audit['old_files_preserved']:,}개와 기존 holdout을 보존했다. branch는 research/costaware-v3, output은 continuation_v3/runtime이다. 새 소스와 producer는 reports/software.lock.json에 고정했다.",'','C++ 기능 검증 → CPU development → metadata 경계 수정 → corrected producer gate → 후보 freeze → 새 input/owner 평가 → 전체 storage와 sparse sensitivity를 완료했다. 전부 실제 실행 자료이며 ORACLE_COST는 아래 성능표에 들어가지 않는다.','','|프로그램|보호법|clean cycles|IPC|normal overhead (%)|모델 storage bits|','|---|---|---:|---:|---:|---:|']
for r in clean:text.append(f"|{r['program']}|{r['variant']}|{r['cycles']}|{r['IPC']:.5f}|{100*(r['cycles']/base[r['program']]-1):+.4f}|{r['total_bits']}|")
text+=['','아래 net은 A=정상 P0, B=오류 P0, C=정상 보호, D=오류 보호의 100(B−D)/A이다. 프로그램별 동일 가중 평균과 owner를 짝지은 95% bootstrap CI(10,000회)다. 각 프로그램의 입력은 하나이며 workload 모집단 CI가 아니다.','','|조건|보호법|net pp [95% CI]|','|---|---|---|']
for r in main['summary']:text.append(f"|{r['scenario']}|{r['variant']}|{fmt(r['metrics']['net_pp'])}|")
text+=['','|노출/희소 조건|보호법|net pp [95% CI]|','|---|---|---|']
for label,data in [('전체 모델 storage, 동일 per-bit rate',whole),('CHARM K, λ=1e−8/cycle',sparse)]:
 for r in data['summary']:text.append(f"|{label}|{r['variant']}|{fmt(r['net_pp'])}|")
text+=['','|단계적 복귀의 N1 대비 추가 이득|net pp [95% CI]|','|---|---|']
for k,v in comparisons.items():text.append(f'|{k}|{fmt(v)}|')
text+=['','P의 P0 대비 이득과 P의 N1 대비 추가 이득을 구분한다. CI가 0을 포함하는 비교는 우위가 입증됐다고 표현하지 않는다. 단일 오류, 반복 군집, 전체 storage 노출, sparse 조건의 우승자를 하나로 합치지 않는다.','','D는 development의 2% normal budget을 초과하여 primary 평가에 넣지 않았다. 거절 이유와 프로그램별 수치는 configs/CANDIDATE_SPEC.lock.json 및 REJECTED_DESIGNS.md에 남겼다. 원래 H1과 비교한 같은 k/source/shadow·같은 서비스 자원의 결과는 reports/B_RESOURCE.json에 있다.','','normal budget은 동일한 유한 source interface를 사용하는 P0에 대한 값이다. source FIFO 자체의 영향을 숨기지 않도록 design 입력의 즉시 갱신 P0 참고 실행도 C_CPU_GATE에 남겼다. 서로 다른 resource contract의 분모를 섞지 않는다.','','검출/정정 성공과 정답 성공은 다르다. parity even-bit, SECDED3+, 상관된 두 TMR copy의 한계를 유지했고 모든 CPU 실행에 native stdout/exit/instruction/event 검증을 적용했다. 실패는 0 cycles로 대체하지 않았다.','','CPU_RESULTS_evaluation.csv와 보고서의 per_program 항목이 프로그램별 A/B/C/D·cycles·IPC 원자료 연결점이다. reports/B_WINDOWS.json은 1k/10k/100k post-event functional windows, source pattern 비교는 B_SOURCE_REPLAY.json이다. H1 synchronous C++ reference를 asynchronous D의 CPU 결과로 쓰지 않았다.','','실제 RTL 지연·PPA·FIT는 측정하지 않았다. 다음 하드웨어 검증 계약과 포함/제외 범위는 HARDWARE_SHORTLIST.md에 있다. HDL/Cadence/SPICE/TCAD는 시작하지 않았다.']
(OUT/'FINAL_REPORT.ko.md').write_text('\n'.join(text)+'\n')
# Selection sensitivity is computed from observed rows; no new hypothesis is tuned.
budgets=[]
for normal in [.25,.5,1,2]:
 for residual in [.5,1,2,5]:
  for v in variants:
   c=[r for r in pairs if r['variant']==v];maxnormal=max(r['clean_overhead_pct'] for r in c)
   per=collections.defaultdict(list)
   for r in c:per[r['program'],r['scenario']].append(r['residual_loss_pp'])
   worst=max(statistics.mean(rr) for rr in per.values())
   budgets.append(dict(variant=v,normal_budget_pct=normal,residual_budget_pp=residual,observed_max_clean_pct=maxnormal,worst_program_scenario_mean_residual_pp=worst,meets=maxnormal<=normal and worst<=residual))
write(OUT/'reports/BUDGET_PARETO.json',dict(status='PREDECLARED_BUDGET_GRID_ANALYSIS',rows=budgets,criterion='worst program clean and worst program/scenario mean residual; tail failure risks separately; no physical PPA ranking',comparison=comparisons))
positive=[s for s in ['SBU_SINGLE','CHARM_6T','CERN_P29_INTERLEAVED'] if comparisons[s]['mean'] is not None and comparisons[s]['CI95'][0]>0]
negative=[s for s in comparisons if comparisons[s]['mean'] is not None and comparisons[s]['CI95'][1]<0]
shortlist=['N1_k64_reference']+(['V3_P_k64_conditional_candidate'] if positive else [])
write(OUT/'reports/HARDWARE_SELECTION.json',dict(status='SOFTWARE_CANDIDATES_FOR_CONDITIONAL_HARDWARE_VALIDATION' if positive else 'NO_ESTABLISHED_NEW_WINNER',shortlist=shortlist,new_P_strictly_positive_primary_comparisons=positive,new_P_strictly_negative_comparisons=negative,physical_PPA_measured=False,RTL_started=False))
(OUT/'HARDWARE_SHORTLIST.md').write_text('# Hardware validation shortlist\n\n'+('The staged candidate has a strict positive matched-owner comparison against N1 in: '+', '.join(positive)+'. This is conditional software evidence; other regimes and physical costs remain separate.\n' if positive else 'No new architecture established a strict positive primary CPU comparison against the lower-cost N1. This round therefore has no established new winner. N1 is retained as the minimal reference for later hardware validation.\n')+'\nShortlist: '+', '.join(shortlist)+'.\n\nThe fixed scope is raw130, path16 and folds200. N1 adds72 logical controller/code cells, and P adds94, a22-cell increment. The prototype finite source interface adds7240 common encoded/control cells; the table totals and per-variant logical manifests are authoritative. Original/protected CPU metadata and retention ownership must also be bound, as specified in RESOURCE_AND_HARDWARE_CONTRACT.md. These counts are not silicon area.\n\nRequired hot FIFO:64×57 bits plus49-bit control. Ready credits:64×55-bit words. Reservations:22 coded bits. P stage control:22 coded bits, qualified-count groups16/44/130, safe CPU/history drains. One dependent source RMW at a time; L/II requirements and drain bounds are in the resource contract. Checker, codec, scoreboard and clear/invalidation ports require physical binding; combinational metadata bandwidth in the software model is an assumption.\n\nReject the physical candidate if measured normal overhead violates the declared budget, if realistic ports/lifetime cause unacceptable backpressure, if matched independent benefit disappears, or if native correctness/resource invariants fail. Parity even-bit and SECDED3+/correlated-copy limitations remain. Source-informed clustering is logical-layout stress rather than a target particle-rate model.\n\nNovelty is the evaluated relationship between state role, useful recovery, actual-commit qualification, event pattern and maintenance cost. General parity, ECC, TMR, partial degradation, checkpointing and history resynchronization are prior art; see NOVELTY_MATRIX.md. D failed the clean budget despite its separate queue and added766 cells versus the combined H1 control. Its negative result and the cost-only upper bounds are part of the result.\n\nHDL/Cadence/SPICE/TCAD remain deferred. Physical latency/PPA or mission FIT has not been demonstrated.\n')
(OUT/'NEW_HOLDOUT.md').write_text('# New holdout execution contract\n\n'+f"Frozen variants: {', '.join(variants)}. Three independently generated evaluation inputs and ten new event owners per program/scenario were used after the corrected producer gate. The mandatory P0/ED/ECC/TMR baselines were retained.\n\n"+'Main scenarios are conditional SBU, CHARM6T K205:9 with λ1e−6/cycle, and representative CERN recorded-K≥2 interleaved footprints at the same normalized stress rate. Whole-storage and sparse λ1e−8 sensitivity have separate independent owner masters and scope contracts. The same evaluation program inputs across these tracks are fixed inputs, not new workload populations.\n\n'+f"Main actual runs: {main['executed_runs']}; failures: {main['failures']}. Whole actual runs: {whole['runs']}; failures: {whole['failed_runs']}. Sparse actual runs: {sparse['runs']}; failures: {sparse['failed_runs']}. No failure became zero cycles. The old holdout was untouched.\n\n"+'Input/ELF/native hashes, corrected producer/config/source hashes, role-separated RNG namespaces, event marks, raw outputs and paired owners are in the locks, reports and review bundle. No policy was retuned using these outcomes.\n')
(OUT/'FINAL_REPORT_NOTES.md').write_text('# Final report notes\n\nUse FINAL_REPORT.ko.md and its actual corrected-producer summaries. Do not merge old v2, development B or ORACLE_COST diagnostics into fresh evaluation counts.\n\nC++ functional P reduced SBU misses, while CPU benefit versus N1 is the separate matched-owner result in reports/NEW_VS_N1.json. Performance recovery is distinct from Phi/base/table equality. Program answers remain exact.\n\nKnown repair semantics and combinational metadata/port assumptions are explicit lower-bound software contracts. An optimal physical protection method is not established without matched library/PVT latency and ownership. The immediate-update P0 reference exposes the common source-interface cost and is not mixed with finite-interface P0 denominators.\n\nRates are normalized stress, not measured target per-bit rates or FIT. CERN recorded coordinate catalogs do not prove independent particle clusters; Flying duplicate74 rows are not MCU. Previously seen source replays and historical HW1 traces are development robustness evidence. Actual CPU programs are public MiBench qsort/dijkstra/SHA1, not official SPEC CPU executable scores.\n\nNo p99/WCET or workload-population guarantee is made from10 owners. Bootstrap resamples owners within each fixed input; programs have equal weight. Failure denominators, right-censored future events and no-event owners are retained.\n')
(OUT/'USER_ACTIONS_REQUIRED.md').write_text('# User actions\n\n현재 software 결과를 재현·검토하기 위한 추가 dataset, SPEC 배포본, license checkout 또는 TCAD 요청은 없다. CPU 평가는 공개 MiBench 실행 파일, trace 분석은 제공 HW1 자료를 사용했다.\n\n다음 하드웨어 단계에서는 storage/metadata 소유권과 ports를 정하고 같은 library/PVT의 실제 latency·PPA를 측정해야 한다. 이번 작업은 HDL 전에 종료하며 Cadence/SPICE/TCAD를 실행하지 않았다.\n')
(OUT/'CURRENT_STATE.md').write_text('# v3 current state\n\nSoftware round completed and raw outputs audited. Source roles, cold recovery and finite service were implemented in the live workspace, on research/costaware-v3. '+f"All {audit['old_files_preserved']:,} old files remain byte-identical. Existing old holdout runs were untouched.\n\n"+'A is the diagnostic/controlled-cost producer; B is development/equal-resource evidence; corrected C is the frozen new-evaluation producer. A staged-metadata retirement counterexample was reproduced and fixed before evaluation. The first C worktree missed two fetch transport files and failed its checksum gate; the failed binary/logs remain archived. No failed gate was promoted.\n\n'+f"Hardware selection: {', '.join(shortlist)}. No physical-cost superiority or HDL completion is claimed. Recorded build/experiment GNU host CPU time: {used_cpu()/3600:.3f} core-hours. This excludes unmetered preparation/analysis bookkeeping and is a round checkpoint, not a user server limit.\n")
decision('G7','Choose hardware validation targets only after matched fresh evaluation and cost controls.', ['FINAL_REPORT.ko.md','reports/NEW_VS_N1.json','reports/BUDGET_PARETO.json','reports/G7_AUDIT.json'], {'shortlist':shortlist,'positive_primary_P_vs_N1':positive,'negative_P_vs_N1':negative}, 'Stop before HDL; bind metadata/ports and measure matched physical latency/cost before claiming hardware superiority.',falsifier='Physical service/control latency violates the2pct budget or new protection does not beat the lower-cost N1 under the intended event regime.')
print('Audited report rendered; shortlist',shortlist,'recorded coreH',used_cpu()/3600)
